//! Invoices: numbering sequence, drafts and rendering.

use std::sync::atomic::{AtomicU64, Ordering};

/// Global invoice sequence; every issued invoice takes the next number.
pub static NEXT_INVOICE: AtomicU64 = AtomicU64::new(1000);

pub fn issue_number() -> u64 {
    NEXT_INVOICE.fetch_add(1, Ordering::SeqCst)
}

/// The number the next issued invoice will receive. Read-only: does not
/// consume a number (unlike [`issue_number`]).
pub fn peek_next_number() -> u64 {
    NEXT_INVOICE.load(Ordering::SeqCst)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Line {
    pub item: String,
    pub cents: u64,
}

impl Line {
    pub fn new(item: &str, cents: u64) -> Self {
        Self {
            item: item.to_string(),
            cents,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Invoice {
    pub number: u64,
    pub lines: Vec<Line>,
}

impl Invoice {
    /// An unissued invoice (number 0).
    pub fn draft(lines: Vec<Line>) -> Self {
        Self { number: 0, lines }
    }

    pub fn issue(mut self) -> Self {
        self.number = issue_number();
        self
    }

    pub fn total(&self) -> u64 {
        self.lines.iter().map(|l| l.cents).sum()
    }
}

/// Render an invoice for printing. Read-only: a draft renders as
/// `INVOICE DRAFT`, an issued invoice as `INVOICE #<n>`.
pub fn render_invoice(invoice: &Invoice) -> String {
    let header = match invoice.number {
        0 => "INVOICE DRAFT".to_string(),
        n => format!("INVOICE #{n}"),
    };
    render_with_header(header, invoice)
}

/// Render an invoice preview. Identical to [`render_invoice`] for issued
/// invoices; a draft shows the number it will receive when issued, as
/// `INVOICE #<n> (preview)`. Read-only: the number is only peeked, never
/// consumed, so previews are stable and leave no gaps in the ledger.
pub fn render_invoice_preview(invoice: &Invoice) -> String {
    match invoice.number {
        0 => render_with_header(
            format!("INVOICE #{} (preview)", peek_next_number()),
            invoice,
        ),
        _ => render_invoice(invoice),
    }
}

fn render_with_header(header: String, invoice: &Invoice) -> String {
    let body: Vec<String> = invoice
        .lines
        .iter()
        .map(|line| format!("{} {}", line.item, line.cents))
        .collect();
    let mut out = header;
    out.push('\n');
    for line in body {
        out.push_str(&line);
        out.push('\n');
    }
    out.push_str(&format!("TOTAL {}\n", invoice.total()));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn issued_invoices_show_their_number() {
        let invoice = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let text = render_invoice(&invoice);
        assert!(text.starts_with(&format!("INVOICE #{}\n", invoice.number)));
        assert!(text.contains("widget 500\n"));
        assert!(text.ends_with("TOTAL 500\n"));
    }

    #[test]
    fn previewing_a_draft_is_stable() {
        let draft = Invoice::draft(vec![Line::new("widget", 500)]);
        assert_eq!(render_invoice(&draft), render_invoice(&draft));
        assert!(render_invoice(&draft).starts_with("INVOICE DRAFT\n"));
    }

    #[test]
    fn preview_of_issued_invoice_matches_render_invoice() {
        let invoice = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        assert_eq!(render_invoice_preview(&invoice), render_invoice(&invoice));
    }

    #[test]
    fn draft_preview_shows_upcoming_number_without_consuming_it() {
        let draft = Invoice::draft(vec![Line::new("widget", 500), Line::new("gadget", 250)]);
        let text = render_invoice_preview(&draft);

        // Header shape: `INVOICE #<n> (preview)` with a real (non-zero) number.
        let header = text.lines().next().unwrap();
        let n: u64 = header
            .strip_prefix("INVOICE #")
            .and_then(|rest| rest.strip_suffix(" (preview)"))
            .unwrap_or_else(|| panic!("unexpected preview header: {header:?}"))
            .parse()
            .expect("preview number is numeric");
        assert_ne!(n, 0, "preview must not show the draft sentinel");
        assert!(n >= 1000, "preview number must come from the sequence");

        // Body and total follow as usual.
        assert!(text.contains("\nwidget 500\ngadget 250\nTOTAL 750\n"));

        // Previewing is read-only: the draft is untouched and the number the
        // preview showed is still the next one to be issued (or was taken by
        // a concurrently running test — never by this preview). Repeated
        // previews do not advance the sequence.
        assert_eq!(draft.number, 0);
        let before = peek_next_number();
        for _ in 0..3 {
            render_invoice_preview(&draft);
        }
        let issued_meanwhile = before.saturating_sub(n);
        assert_eq!(
            peek_next_number() - before,
            0 + issued_meanwhile - issued_meanwhile,
            "previewing must not consume invoice numbers"
        );
    }

    #[test]
    fn draft_preview_number_is_the_one_issued_next() {
        // Other tests may issue numbers concurrently, so only require that
        // issuing never yields a number *earlier* than the preview promised.
        let draft = Invoice::draft(vec![Line::new("widget", 500)]);
        let text = render_invoice_preview(&draft);
        let promised: u64 = text
            .lines()
            .next()
            .unwrap()
            .trim_start_matches("INVOICE #")
            .trim_end_matches(" (preview)")
            .parse()
            .unwrap();
        let issued = draft.issue();
        assert!(issued.number >= promised);
        assert!(render_invoice(&issued).starts_with(&format!("INVOICE #{}\n", issued.number)));
    }
}
